#include <iostream>

using namespace std;

bool judge(long int n)
{
    return n % 2 != 0;
}

int main()
{
    long int han, ten;
    long int temp;
    long int count = 0;
    long int a, b;

    cin >> han >> ten;

    a = han / 4;
    b = ten / 4;
    temp = a < b ? a : b;

    if (temp == a)
    {
        han %= 4;
        ten -= temp * 4;
    }
    else
    {
        han -= temp * 4;
        ten %= 4;
    }

    if (han >= 2 && ten >= 2)
    {
        count++;
        han -= 2;
        ten -= 2;
    }

    if (han == 1 && ten >= 12)
    {
        count++;
        han = 0;
        ten -= 12;
    }

    if (han == 0)
        count += ten / 22;

    cout << (judge(count) ? "Ciel" : "Hanako");
    return 0;
}

